// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';


export type GoldilocksProps = Record<string, any>;

const GlowHalo: React.FC<{ progress: number; color: string }> = ({ progress, color }) => {
  return (
    <div
      style={{
        position: "absolute",
        left: -20,
        top: -60,
        width: 300,
        height: 300,
        backgroundColor: color,
        borderRadius: "50%",
        transform: `scale(${interpolate(progress, [0, 1], [0.5, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" })})`,
        filter: "blur(60px)",
        opacity: progress * 0.7,
        zIndex: -1,
      }}
    />
  );
};

const ImpactLines: React.FC<{ progress: number; color: string }> = ({ progress, color }) => {
  if (progress === 0 || progress === 1) return null;
  return (
    <div
      style={{
        position: "absolute",
        width: 200,
        height: 100,
        top: 0,
        left: 30,
        display: "flex",
        justifyContent: "center",
        alignItems: "flex-end",
        zIndex: 0,
      }}
    >
      {[...Array(5)].map((_, i) => {
        const angle = (Math.PI / 4) * i - Math.PI;
        const distance = interpolate(progress, [0, 1], [30, 100]);
        const opacity = interpolate(progress, [0, 0.5, 1], [0, 1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
        const x = Math.cos(angle) * distance;
        const y = Math.sin(angle) * distance;

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              width: 6,
              height: 25,
              backgroundColor: color,
              borderRadius: 3,
              transform: `translate(${x}px, ${y}px) rotate(${angle + Math.PI / 2}rad)`,
              opacity,
            }}
          />
        );
      })}
    </div>
  );
};

const BedRender: React.FC<{
  baseColor: string;
  mattressColor: string;
  blanketColor: string;
  stiffAmount?: number;
  squishAmount?: number;
}> = ({ baseColor, mattressColor, blanketColor, stiffAmount = 0, squishAmount = 0 }) => {
  const mHeight = interpolate(squishAmount, [0, 1], [40, 15], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const mWidth = interpolate(squishAmount, [0, 1], [210, 230], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const mRadius = interpolate(stiffAmount, [0, 1], [20, 4], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  return (
    <div
      style={{
        position: "relative",
        width: 260,
        height: 180,
        display: "flex",
        flexDirection: "column",
        alignItems: "flex-start",
        justifyContent: "flex-end",
        transformOrigin: "bottom center",
      }}
    >
      {/* Headboard (Far left for right-facing side profile) */}
      <div style={{ position: "absolute", left: 12, bottom: 20, width: 24, height: 110, backgroundColor: baseColor, borderRadius: 12, zIndex: 0 }} />

      {/* Single Pillow (Resting against headboard) */}
      <div style={{ zIndex: 2, marginBottom: -6, marginLeft: 32, transform: `translateY(${squishAmount * 10}px)` }}>
        <div style={{ width: 55, height: 26, backgroundColor: "#FFFFFF", borderRadius: 13 }} />
      </div>

      {/* Mattress */}
      <div
        style={{
          width: mWidth,
          height: mHeight,
          backgroundColor: mattressColor,
          borderRadius: mRadius,
          position: "relative",
          overflow: "hidden",
          marginLeft: 24,
          zIndex: 1,
        }}
      >
        {/* Blanket covering the right half (foot of the bed) */}
        <div
          style={{
            position: "absolute",
            right: 0,
            top: 0,
            width: "60%",
            height: "100%",
            backgroundColor: blanketColor,
          }}
        />
      </div>

      {/* Bed Base (Frame) */}
      <div style={{ width: 220, height: 24, backgroundColor: baseColor, borderRadius: 12, marginTop: 4, marginLeft: 24, zIndex: 1 }} />

      {/* Legs */}
      <div style={{ display: "flex", justifyContent: "space-between", width: 180, marginLeft: 44, marginTop: -12, zIndex: 0 }}>
        <div style={{ width: 24, height: 35, backgroundColor: baseColor, borderRadius: 12 }} />
        <div style={{ width: 24, height: 35, backgroundColor: baseColor, borderRadius: 12 }} />
      </div>
    </div>
  );
};

const GoldilocksAnimation: React.FC<GoldilocksProps> = ({
  backgroundColor = "#29b0c3",
  transparentBackground = false,
  durationInSeconds = 12,
  woodColor = "#B08D6A",
  hardMattressColor = "#E0DCD9",
  softMattressColor = "#DCE8F2",
  perfectMattressColor = "#FFFFFF",
  blanketColor = "#F28C73",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timing Markers
  const totalFrames = durationInSeconds * fps;
  const fAppear = Math.floor(totalFrames * 0.05);
  const fHardStart = Math.floor(totalFrames * 0.22);
  const fSoftStart = Math.floor(totalFrames * 0.44);
  const fExit = Math.floor(totalFrames * 0.66);
  const fJustRightEnter = Math.floor(totalFrames * 0.72);

  // ----- Bed 1 Logic ("Too Hard") -----
  const appearSpring1 = spring({ frame: Math.max(0, frame - fAppear), fps, config: { damping: 12 } });
  const hardProgress = Math.max(0, frame - fHardStart);
  const hardYOffset = interpolate(
    hardProgress,
    [0, 10, 15, 18, 21, 24, 27],
    [0, -150, 0, -30, 0, -10, 0],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );
  const stiffAmount = interpolate(hardProgress, [0, 10], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const hardRotation = interpolate(hardProgress, [0, 10, 15], [0, -8, 0], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const hardHitProgress = interpolate(hardProgress, [15, 30], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const exitSpring1 = spring({ frame: Math.max(0, frame - fExit), fps, config: { damping: 15 } });

  const bed1X = interpolate(appearSpring1, [0, 1], [-width * 0.5, width * 0.5]) + interpolate(exitSpring1, [0, 1], [0, -width]);
  const bed1Scale = appearSpring1 * 1.5;

  // ----- Bed 2 Logic ("Too Soft") -----
  const appearSpring2 = spring({ frame: Math.max(0, frame - (fAppear + 10)), fps, config: { damping: 12 } });
  const softSpring = spring({ frame: Math.max(0, frame - fSoftStart), fps, config: { damping: 12, stiffness: 80 } });
  const exitSpring2 = spring({ frame: Math.max(0, frame - (fExit + 5)), fps, config: { damping: 15 } });

  const bed2X = interpolate(appearSpring2, [0, 1], [width * 1.5, width * 0.5]) + interpolate(exitSpring2, [0, 1], [0, width]);
  const bed2Scale = appearSpring2 * 1.5;
  const squishAmount = softSpring;

  // ----- Bed 3 Logic ("Just Right") -----
  const appearSpring3 = spring({ frame: Math.max(0, frame - fJustRightEnter), fps, config: { damping: 12, stiffness: 100 } });
  const bed3LocalFrame = Math.max(0, frame - fJustRightEnter);
  const floatOpacity = interpolate(appearSpring3, [0.8, 1], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const bed3BounceY = Math.sin(bed3LocalFrame / 10) * 8 * floatOpacity;

  const bed3X = width * 0.5;
  const bed3EnterY = interpolate(appearSpring3, [0, 1], [height * 0.5, 0]);
  const bed3Scale = appearSpring3 * 1.8;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none", overflow: "hidden" }}>
      {/* Bed 1 - Too Hard */}
      <div
        style={{
          position: "absolute",
          left: bed1X,
          top: height * 0.4,
          width: 260,
          height: 180,
          transform: `translate(-50%, -100%) scale(${bed1Scale}) translateY(${hardYOffset}px) rotate(${hardRotation}deg)`,
          transition: "none",
        }}
      >
        <ImpactLines progress={hardHitProgress} color="#A0A0A0" />
        <BedRender baseColor={woodColor} mattressColor={hardMattressColor} blanketColor={blanketColor} stiffAmount={stiffAmount} />
      </div>

      {/* Bed 2 - Too Soft */}
      <div
        style={{
          position: "absolute",
          left: bed2X,
          top: height * 0.8,
          width: 260,
          height: 180,
          transform: `translate(-50%, -100%) scale(${bed2Scale})`,
          transition: "none",
        }}
      >
        <BedRender baseColor={woodColor} mattressColor={softMattressColor} blanketColor={blanketColor} squishAmount={squishAmount} />
      </div>

      {/* Bed 3 - Just Right */}
      <div
        style={{
          position: "absolute",
          left: bed3X,
          top: height * 0.6,
          width: 260,
          height: 180,
          transform: `translate(-50%, -100%) scale(${bed3Scale}) translateY(${bed3EnterY + bed3BounceY}px)`,
          transition: "none",
        }}
      >
        <GlowHalo progress={appearSpring3} color="#FFFFFF" />
        <BedRender baseColor={woodColor} mattressColor={perfectMattressColor} blanketColor={blanketColor} />
      </div>
    </AbsoluteFill>
  );
};

export default GoldilocksAnimation;